import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"创建与配置 Agent","description":"","frontmatter":{"title":"创建与配置 Agent"},"headers":[],"relativePath":"zh/guide/agents.md","filePath":"zh/guide/agents.md"}'),d={name:"zh/guide/agents.md"};function l(i,t,o,h,s,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="创建与配置-agent" tabindex="-1">创建与配置 Agent <a class="header-anchor" href="#创建与配置-agent" aria-label="Permalink to &quot;创建与配置 Agent&quot;">​</a></h1><h2 id="创建独立-agent" tabindex="-1">创建独立 Agent <a class="header-anchor" href="#创建独立-agent" aria-label="Permalink to &quot;创建独立 Agent&quot;">​</a></h2><ol><li>在 Agent 列表选择<strong>新建 Agent</strong>。</li><li>填写名称、描述和系统提示词，明确任务范围、输出格式和禁止执行的操作。</li><li>按需设置工作目录。目录是工具可操作的运行现场，不要用不相关的系统目录或敏感资料目录代替。</li><li>只勾选任务需要的内置工具、MCP、知识库和工作流。</li><li>保存后进入对话，用一个无副作用的小任务验证配置。</li></ol><h2 id="能力配置的区别" tabindex="-1">能力配置的区别 <a class="header-anchor" href="#能力配置的区别" aria-label="Permalink to &quot;能力配置的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>适用场景</th><th>配置前提</th></tr></thead><tbody><tr><td>内置工具</td><td>文件、搜索等已提供能力</td><td>检查具体工具权限、目录和外部服务条件</td></tr><tr><td>技能</td><td>为任务提供方法和操作约定</td><td>先准备公共或 Agent 专属技能</td></tr><tr><td>MCP 工具</td><td>连接外部工具服务</td><td>工具已启用，协议与地址配置有效</td></tr><tr><td>知识库</td><td>检索参考资料</td><td>文本／向量库及其模型依赖已就绪</td></tr><tr><td>工作流工具</td><td>把确定的流程作为工具调用</td><td>流程已启用，并使用同步或异步 API 触发</td></tr></tbody></table><p>只有符合触发条件并启用的工作流会出现在工作流工具列表。普通手动流程不能直接被当成此类工具；<a href="./../sub_workflow.html">子流程</a>是另一种流程编排方式。</p><h2 id="内置-agent" tabindex="-1">内置 Agent <a class="header-anchor" href="#内置-agent" aria-label="Permalink to &quot;内置 Agent&quot;">​</a></h2><p>在主 Agent 卡片的操作菜单中添加内置 Agent，它归属于主卡，在卡片的内置区域管理。它与独立 Agent 的归属、导入导出和删除行为不同；需要改变归属时使用界面提供的升级操作，而不是手动复制配置。</p><p>详见<a href="./sub-agents.html">组合子 Agent</a>。</p><h2 id="导入与导出" tabindex="-1">导入与导出 <a class="header-anchor" href="#导入与导出" aria-label="Permalink to &quot;导入与导出&quot;">​</a></h2><p>导入、导出用于迁移 Agent 配置。接收外部配置前检查提示词、工具、工作目录和外部地址；不要把配置文件视为可信代码，也不要在公开配置中放入 API Key、Secret 或个人信息。</p><h2 id="验证与排查" tabindex="-1">验证与排查 <a class="header-anchor" href="#验证与排查" aria-label="Permalink to &quot;验证与排查&quot;">​</a></h2><ul><li><strong>工具未出现：</strong> 检查工具是否已创建并启用，以及当前项目和角色。</li><li><strong>模型无法使用：</strong> 在对话页的模型设置提示中完成配置，Agent 表单中的工具选择不能替代模型配置。</li><li><strong>执行了非预期操作：</strong> 立即停用相关通道或定时任务，收紧提示词与工具选择，并检查已有执行记录。</li></ul>',13)])])}const A=e(d,[["render",l]]);export{u as __pageData,A as default};
